<?php
function bit($value) {
    if ($value) {
        return "1";
    }
    return "0";
}

function row($label, $left, $right) {
    echo $label, ":",
        bit($left == $right),
        bit($left != $right),
        bit($left < $right),
        bit($left <= $right),
        bit($left > $right),
        bit($left >= $right),
        "\n";
}

